import { clsx, type ClassValue } from "clsx";
import { extendTailwindMerge } from "tailwind-merge";

const twMerge = extendTailwindMerge({
  extend: { theme: { radius: ["control", "surface", "overlay"], shadow: ["overlay"] } },
});

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

"use client";
import type { ComponentProps, CSSProperties } from "react";
import { cn } from "./lib/cn";
import "./newton-cradle.css";

export type NewtonCradleProps = Omit<ComponentProps<"div">, "children"> & {
  /** Names what is happening, e.g. "Syncing". Pass "" when a visible label sits beside it. */
  label?: string;
  /** Balls in the row, 3 to 7. */
  balls?: number;
  /** Holds the balls at rest. */
  paused?: boolean;
  size?: "sm" | "md" | "lg";
};

/**
 * A desk cradle as a loading indicator: the end ball swings out and falls back, the row passes the knock along
 * and the ball at the other end swings out in turn. One cycle takes 1.4 seconds with the swing slowing at the
 * top and quickening through the bottom, as a pendulum does. It reads as "working, and it will take a moment"
 * more calmly than a spinner. Under reduced motion the balls hold still with one raised.
 */
export function NewtonCradle({ label = "Loading", balls = 5, paused, size = "md", className, style, ...props }: NewtonCradleProps) {
  const count = Math.max(3, Math.min(7, Math.round(balls)));
  return (
    <div
      role={label ? "status" : undefined}
      aria-label={label || undefined}
      aria-hidden={label ? undefined : true}
      data-slot="newton-cradle"
      data-size={size}
      data-paused={paused ? "" : undefined}
      className={cn("inline-grid", className)}
      style={style}
      {...props}
    >
      <span data-slot="nc-frame" style={{ "--nc-n": count } as CSSProperties}>
        {Array.from({ length: count }, (_, index) => (
          <i key={index} data-slot="nc-ball" data-end={index === 0 ? "left" : index === count - 1 ? "right" : undefined} />
        ))}
      </span>
    </div>
  );
}

/* newton-cradle.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  /* Newton cradle: end balls swing in turn on a 1.4s cycle; the swing eases out going up and in coming down. */
  [data-slot="newton-cradle"] { --nc-r: 11px; --nc-len: 36px; --nc-t: 1.4s; color: var(--foreground); }
  [data-slot="newton-cradle"][data-size="sm"] { --nc-r: 7px; --nc-len: 22px; }
  [data-slot="newton-cradle"][data-size="lg"] { --nc-r: 16px; --nc-len: 52px; }
  [data-slot="newton-cradle"] [data-slot="nc-frame"] { position: relative; display: flex; padding: 3px calc(var(--nc-r) * 0.6) 0; }
  [data-slot="newton-cradle"] [data-slot="nc-frame"]::before { content: ""; position: absolute; inset: 0 0 auto; height: 3px; border-radius: 2px; background: var(--border-strong); }
  [data-slot="newton-cradle"] [data-slot="nc-ball"] { position: relative; flex: none; width: calc(var(--nc-r) * 2); height: calc(var(--nc-len) + var(--nc-r) * 2); transform-origin: 50% 0; background: linear-gradient(var(--border-strong), var(--border-strong)) 50% 0 / 1px var(--nc-len) no-repeat; }
  [data-slot="newton-cradle"] [data-slot="nc-ball"]::after { content: ""; position: absolute; inset: auto 0 0; aspect-ratio: 1; border-radius: 50%; background: currentColor; box-shadow: inset calc(var(--nc-r) * 0.18) calc(var(--nc-r) * 0.18) 0 color-mix(in oklab, var(--background) 24%, transparent); }
  [data-slot="newton-cradle"] [data-slot="nc-ball"][data-end="left"] { animation: nc-left var(--nc-t) infinite; }
  [data-slot="newton-cradle"] [data-slot="nc-ball"][data-end="right"] { animation: nc-right var(--nc-t) infinite; }
  [data-slot="newton-cradle"][data-paused] [data-slot="nc-ball"] { animation-play-state: paused; }
  @media (prefers-reduced-motion: reduce) {
    [data-slot="newton-cradle"] [data-slot="nc-ball"][data-end] { animation: none; }
    [data-slot="newton-cradle"] [data-slot="nc-ball"][data-end="left"] { rotate: 24deg; }
  }
  @keyframes nc-left { 0% { rotate: 0deg; animation-timing-function: ease-out; } 25% { rotate: 38deg; animation-timing-function: ease-in; } 50%, 100% { rotate: 0deg; } }
  @keyframes nc-right { 0%, 50% { rotate: 0deg; animation-timing-function: ease-out; } 75% { rotate: -38deg; animation-timing-function: ease-in; } 100% { rotate: 0deg; } }
}
